CREATE FUNCTION public.sante_rejet_entree_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.mfa_conforme() THEN RAISE EXCEPTION 'MFA requise' USING ERRCODE='42501'; END IF; IF NEW.montant IS NOT NULL AND (NEW.montant::text IN ('NaN','Infinity','-Infinity') OR NEW.montant<=0 OR NEW.montant<>trunc(NEW.montant)) THEN RAISE EXCEPTION 'Montant FCFA invalide'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER sante_rejet_guard BEFORE INSERT ON public.sante_tiers_rejets FOR EACH ROW EXECUTE FUNCTION public.sante_rejet_entree_guard();
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='sante_rejet_tiers'; d:=replace(d,'  SELECT * INTO _f FROM sante_factures WHERE id = _facture_id FOR UPDATE;', '  IF NOT public.mfa_conforme() THEN RAISE EXCEPTION ''MFA requise'' USING ERRCODE=''42501''; END IF; IF _montant IS NOT NULL AND (_montant::text IN (''NaN'',''Infinity'',''-Infinity'') OR _montant<>trunc(_montant)) THEN RAISE EXCEPTION ''Montant FCFA entier requis''; END IF; SELECT * INTO _f FROM sante_factures WHERE id = _facture_id FOR UPDATE;'); IF d IS NULL OR position('Montant FCFA entier requis' in d)=0 THEN RAISE EXCEPTION 'Définition de rejet incompatible'; END IF; EXECUTE d; END; $$;
CREATE FUNCTION public.sante_planning_verrou() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.membership_id IS NOT NULL THEN PERFORM 1 FROM public.structure_memberships WHERE id=NEW.membership_id FOR UPDATE; END IF; IF NEW.employee_id IS NOT NULL THEN PERFORM 1 FROM public.employees WHERE id=NEW.employee_id FOR UPDATE; END IF; IF NOT isfinite(NEW.debut) OR NOT isfinite(NEW.fin) THEN RAISE EXCEPTION 'Dates de planning invalides'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER sante_00_planning_verrou BEFORE INSERT OR UPDATE ON public.sante_plannings FOR EACH ROW EXECUTE FUNCTION public.sante_planning_verrou();
CREATE FUNCTION public.sante_personnel_montants_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.forfait_garde::text IN ('NaN','Infinity','-Infinity') OR NEW.forfait_astreinte::text IN ('NaN','Infinity','-Infinity') OR NEW.forfait_garde<0 OR NEW.forfait_astreinte<0 OR NEW.forfait_garde<>trunc(NEW.forfait_garde) OR NEW.forfait_astreinte<>trunc(NEW.forfait_astreinte) THEN RAISE EXCEPTION 'Forfaits FCFA entiers positifs ou nuls requis'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER sante_personnel_montants BEFORE INSERT OR UPDATE ON public.sante_personnel_parametres FOR EACH ROW EXECUTE FUNCTION public.sante_personnel_montants_guard();
CREATE POLICY personnel_mfa ON public.sante_personnel_parametres AS RESTRICTIVE FOR ALL TO authenticated USING(public.mfa_conforme()) WITH CHECK(public.mfa_conforme());
CREATE POLICY planning_mfa ON public.sante_plannings AS RESTRICTIVE FOR ALL TO authenticated USING(public.mfa_conforme()) WITH CHECK(public.mfa_conforme());
CREATE FUNCTION public.sante_revoquer_portail(_patient_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; n integer; BEGIN SELECT structure_id INTO sid FROM public.sante_patients WHERE id=_patient_id; IF auth.uid() IS NULL OR NOT public.mfa_conforme() OR NOT public.has_any_medical_role(sid,ARRAY['admin_structure','secretaire','medecin','biologiste']) THEN RAISE EXCEPTION 'Accès refusé' USING ERRCODE='42501'; END IF; UPDATE public.sante_portail_patient SET utilise=true,expire_le=least(expire_le,now()) WHERE patient_id=_patient_id AND structure_id=sid AND expire_le>now(); GET DIAGNOSTICS n=ROW_COUNT; INSERT INTO public.medical_access_log(structure_id,patient_id,user_id,ecran,motif) VALUES(sid,_patient_id,auth.uid(),'portail','Accès portail révoqués'); RETURN n; END; $$;
REVOKE ALL ON FUNCTION public.sante_revoquer_portail(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sante_revoquer_portail(uuid) TO authenticated;